// Original, quiet music and foley synthesized locally. No recordings or voices.
export class StoryAudio{
 constructor(){this.context=null;this.muted=false;this.timer=null;this.step=0;this.started=false;try{this.muted=localStorage.getItem('possum-muted')==='true'}catch{}document.addEventListener('visibilitychange',()=>{if(!this.context)return;if(document.hidden)this.context.suspend();else if(this.started)this.context.resume().catch(()=>{})})}
 async start(){try{if(!this.context){const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;this.context=new AudioContext();this.master=this.context.createGain();this.master.gain.value=this.muted?0:.3;this.master.connect(this.context.destination)}await this.context.resume();if(!this.started){this.started=true;this.music();this.timer=setInterval(()=>this.music(),680)}}catch{/* The book remains usable if the device cannot play audio. */}}
 toggle(){this.muted=!this.muted;if(this.master)this.master.gain.setTargetAtTime(this.muted?0:.3,this.context.currentTime,.06);try{localStorage.setItem('possum-muted',this.muted)}catch{}return this.muted}
 tone(freq,duration=.5,volume=.1,type='sine',delay=0){if(!this.context)return;const t=this.context.currentTime+delay,o=this.context.createOscillator(),g=this.context.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume,t+.018);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(this.master);o.start(t);o.stop(t+duration+.02)}
 music(){if(!this.context||this.context.state!=='running')return;const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23,261.63,329.63,392,523.25,293.66,349.23,329.63,293.66];this.tone(notes[this.step%16],1.8,.055);if(this.step%4===0)this.tone(notes[this.step%16]/2,2.7,.035,'sine');this.step++}
 click(){this.tone(620,.11,.13);this.tone(890,.12,.04,'sine',.03)}
 noise(duration,volume,filterFreq){if(!this.context)return;const ctx=this.context,b=ctx.createBuffer(1,ctx.sampleRate*duration,ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1);const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),g=ctx.createGain();source.buffer=b;filter.type='lowpass';filter.frequency.value=filterFreq;g.gain.setValueAtTime(.001,ctx.currentTime);g.gain.linearRampToValueAtTime(volume,ctx.currentTime+.08);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);source.connect(filter);filter.connect(g);g.connect(this.master);source.start();source.stop(ctx.currentTime+duration)}
 paper(){this.noise(.65,.12,1700)}
 growl(){this.noise(.65,.13,380);this.tone(89,.5,.1,'triangle');this.tone(73,.55,.07,'triangle',.16)}
 sparkle(){[523.25,659.25,783.99,1046.5].forEach((f,i)=>this.tone(f,.7,.15,'sine',i*.105))}
}
